// The Android compile harness (Spec 129 Task 4; design.md § 2). Three modules, one Gradle build:
//   :tokens  the consumer's generated Kotlin only
//   :probe   generated by scripts/harness/probe-kotlin.ts from the token index; depends on :tokens
//   :dp      the generated Kotlin plus every non-test packaged .kt, with Icon-Base's res/ as its resources
// Nothing here names a source file. lane.ts writes the lists the modules compile (HARNESS_LANE_DIR).
//
// NOT YET RUN: written without a Gradle toolchain (Peter has not approved the downloads).

pluginManagement {
    repositories {
        google()
        mavenCentral()
        gradlePluginPortal()
    }
}

dependencyResolutionManagement {
    repositoriesMode.set(RepositoriesMode.FAIL_ON_PROJECT_REPOS)
    repositories {
        google()
        mavenCentral()
    }
}

rootProject.name = "dp-harness-android"
include(":tokens", ":probe", ":dp")
